ATFGLevelThreePrototypeWorld::ATFGLevelThreePrototypeWorld(){PrimaryActorTick.bCanEverTick=false;SceneRoot=CreateDefaultSubobject<USceneComponent>(TEXT("SceneRoot"));SetRootComponent(SceneRoot);Geometry=CreateDefaultSubobject<UInstancedStaticMeshComponent>(TEXT("PrototypeGeometry"));Geometry->SetupAttachment(SceneRoot);Geometry->SetCollisionEnabled(ECollisionEnabled::QueryAndPhysics);Geometry->SetCollisionResponseToAllChannels(ECR_Block);static ConstructorHelpers::FObjectFinder<UStaticMesh>Cube(TEXT("/Engine/BasicShapes/Cube.Cube"));if(Cube.Succeeded())Geometry->SetStaticMesh(Cube.Object);}void ATFGLevelThreePrototypeWorld::BeginPlay(){Super::BeginPlay();AddBox(FVector(2300,0,-75),FVector(50,10,.75));AddBox(FVector(2300,1050,280),FVector(50,.6,3.6));AddBox(FVector(2300,-1050,280),FVector(50,.6,3.6));for(int32 I=0;I<8;++I){float X=500+I*480;float T=I%2==0?5.f:-7.f;AddBox(FVector(X,650,165),FVector(2,2.3,3.3),FRotator(0,T,0));AddBox(FVector(X+170,-650,150),FVector(1.8,2.1,3),FRotator(0,-T,0));}AddBox(FVector(3150,0,250),FVector(6,5,5));AddBox(FVector(4050,-300,300),FVector(1.2,1.2,6));AddBox(FVector(4050,300,300),FVector(1.2,1.2,6));AddBox(FVector(4050,0,620),FVector(1.2,4.5,1));SpawnCheckpoint(FVector(180,0,90),TEXT("L03_Start"));SpawnInteraction(FVector(550,0,80),FText::FromString(TEXT("Enter the breached royal avenue")),TEXT("RoyalAvenueBreach"),0,1,FText::FromString(TEXT("Kael")),FText::FromString(TEXT("The palace banners are burning. They reached the royal district faster than anyone thought possible.")));SpawnEncounter(FVector(1250,0,40),1,2,3,false);SpawnCheckpoint(FVector(1700,0,90),TEXT("L03_RoyalAvenue"));FActorSpawnParameters P;P.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;if(auto*S=GetWorld()->SpawnActor<ATFGRelicPickupActor>(ATFGRelicPickupActor::StaticClass(),FVector(2100,0,90),FRotator::ZeroRotator,P)){S->InteractionId=TEXT("AetherianGateShard01");S->InteractionPrompt=FText::FromString(TEXT("Touch the reacting Aetherian shard"));S->QuestId=QuestId;S->RequiredQuestStage=2;S->AdvanceQuestToStage=3;S->RelicId=TEXT("Relic_AetherianGateShard_01");S->ItemId=TEXT("AetherianGateShard");S->Quantity=1;S->DisciplineId=TEXT("Gatefire");S->MasteryAmount=1;S->AbilityUnlockId=TEXT("GatefireEcho");S->SpeakerName=FText::FromString(TEXT("The Shard"));S->StoryLine=FText::FromString(TEXT("The fragment warms beneath your hand. For one breath, lines of pale Gatefire answer from beneath your skin."));S->RefreshPresentation();}SpawnEncounter(FVector(2700,0,40),3,4,4,true);SpawnCheckpoint(FVector(3150,0,90),TEXT("L03_PalaceSteps"));SpawnInteraction(FVector(3500,0,90),FText::FromString(TEXT("Activate the old defensive ward")),TEXT("PalaceWardStone"),4,5,FText::FromString(TEXT("Kael")),FText::FromString(TEXT("The shard reacts again. The old ward accepts the spark and the palace barrier flickers back to life.")));SpawnInteraction(FVector(4050,0,110),FText::FromString(TEXT("Reach the royal hall")),TEXT("RoyalHallDoors"),5,6,FText::FromString(TEXT("Royal Guard")),FText::FromString(TEXT("Kael! The inner hall is still standing—but the princess is trapped somewhere beyond these doors.")),true);}void ATFGLevelThreePrototypeWorld::AddBox(const FVector&L,const FVector&S,const FRotator&R){if(Geometry)Geometry->AddInstance(FTransform(R,L,S));}ATFGInteractableActor*ATFGLevelThreePrototypeWorld::SpawnInteraction(const FVector&L,const FText&Pm,FName Id,int32 Req,int32 Adv,const FText&Sp,const FText&Line,bool Complete){FActorSpawnParameters P;P.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;auto*A=GetWorld()->SpawnActor<ATFGInteractableActor>(ATFGInteractableActor::StaticClass(),L,FRotator::ZeroRotator,P);if(A){A->InteractionPrompt=Pm;A->InteractionId=Id;A->QuestId=QuestId;A->RequiredQuestStage=Req;A->AdvanceQuestToStage=Adv;A->bCompleteQuest=Complete;A->bOneShot=true;A->SpeakerName=Sp;A->StoryLine=Line;A->RefreshPresentation();}return A;}ATFGEncounterZone*ATFGLevelThreePrototypeWorld::SpawnEncounter(const FVector&L,int32 Req,int32 Adv,int32 Count,bool Brute){FActorSpawnParameters P;P.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AlwaysSpawn;auto*E=GetWorld()->SpawnActor<ATFGEncounterZone>(ATFGEncounterZone::StaticClass(),L,FRotator::ZeroRotator,P);if(E){E->QuestId=QuestId;E->RequiredQuestStage=Req;E->AdvanceQuestToStage=Adv;int32 N=Brute?FMath::Max(0,Count-1):Count;for(int32 I=0;I<N;++I)E->EnemyClasses.Add(ATFGEnemyCharacter::StaticClass());if(Brute)E->EnemyClasses.Add(ATFGVeyrBruteEnemy::StaticClass());}return E;}void ATFGLevelThreePrototypeWorld::SpawnCheckpoint(const FVector&L,FName Id){FActorSpawnParameters P;P.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AlwaysSpawn;if(auto*C=GetWorld()->SpawnActor<ATFGCheckpointActor>(ATFGCheckpointActor::StaticClass(),L,FRotator::ZeroRotator,P))C->ConfigureCheckpoint(Id,TEXT("L03_PalaceUnderSiege"),true);}
